export const DOMAIN_CORE = 1 << 0;              // 1: Universal math & calculus basics
export const DOMAIN_CALCULUS = 1 << 1;          // 2: Differentials, limits, integrals
export const DOMAIN_LINEAR_ALGEBRA = 1 << 2;    // 4: Matrices, rank, trace, span, eigenvalues
export const DOMAIN_QUANTUM = 1 << 3;           // 8: Bra-ket, operators, spin, commutators
export const DOMAIN_PHYSICS = 1 << 4;           // 16: Physics vectors, tensors, coordinate frames
export const DOMAIN_UNITS = 1 << 5;             // 32: SI units and physical dimensions
export const DOMAIN_ABSTRACT_ALGEBRA = 1 << 6; // 64: Groups, rings, fields, hom, ker, aut
export const DOMAIN_ML_STATS = 1 << 7;          // 128: relu, gelu, softmax, distributions
export const DOMAIN_ALL = 0xFFFFFFFF;

// Dialect Bitmasks
export const DIALECT_LATEX = 1 << 0;     // 1: LaTeX / MathJax 4 core
export const DIALECT_TYPST = 1 << 1;     // 2: Typst Math
export const DIALECT_ASCIIMATH = 1 << 2; // 4: AsciiMath
export const DIALECT_MATLAB = 1 << 3;    // 8: MATLAB / GNU Octave
export const DIALECT_PYTHON = 1 << 4;    // 16: Python / SymPy
export const DIALECT_WOLFRAM = 1 << 5;   // 32: Wolfram Language
export const DIALECT_ALL = 0xFFFFFFFF;

export function getActiveDialects(options?: {
  dialectLatex?: boolean;
  dialectTypst?: boolean;
  dialectAsciiMath?: boolean;
  dialectMatlab?: boolean;
  dialectPython?: boolean;
  dialectWolfram?: boolean;
}): number {
  if (!options) return DIALECT_ALL;
  let mask = DIALECT_ALL;
  if (options.dialectLatex === false) mask &= ~DIALECT_LATEX;
  if (options.dialectTypst === false) mask &= ~DIALECT_TYPST;
  if (options.dialectAsciiMath === false) mask &= ~DIALECT_ASCIIMATH;
  if (options.dialectMatlab === false) mask &= ~DIALECT_MATLAB;
  if (options.dialectPython === false) mask &= ~DIALECT_PYTHON;
  if (options.dialectWolfram === false) mask &= ~DIALECT_WOLFRAM;
  return mask >>> 0;
}

export type CatalogRole =
  | "function"
  | "parameter"
  | "constant"
  | "operator"
  | "differential"
  | "delimiter"
  | "relation"
  | "unit"
  | "variable";

export interface CatalogEntry {
  key: string;
  role: CatalogRole;
  priority: number;
  domains: number;
  dialects?: number;
  tier: number; // 0 = standard macro, 1 = Tier 1 bare function, 2 = Tier 2 bare function
  arity?: number; // 1 for font macro roots like \mathbb, \mathbf, bb, bold
  canonical?: string;
  unicode?: string;
  extensible?: boolean; // true for \overbrace, \underbrace, etc.
  uncolored?: boolean;  // true for \lim, \limsup, etc.
  package?: string;
}

export interface CatalogMatch {
  length: number;
  entry: CatalogEntry;
}

const N = 7342;
const M = 4096;
const MASK = 4095;

// 32-bit FNV-1a hash
function fnv1a(str: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

